/**
 * Cloudflare Worker entry: the OpenNext-generated Next.js worker plus a
 * scheduled (cron) handler. The cron calls the app's own protected endpoint
 * to release expired payment holds, so all database logic stays in Next.js.
 *
 * Built by `npm run cf:build`; referenced by wrangler.jsonc → "main".
 */
// @ts-ignore — generated by the OpenNext build
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string };

export default {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) {
      console.error("[cron] CRON_SECRET is not set; skipping hold release");
      return;
    }
    const request = new Request("https://cron.internal/api/cron/release-holds", {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      handler
        .fetch(request, env, ctx)
        .then(async (res: Response) => {
          const body = await res.text();
          if (res.ok) console.log("[cron] release-holds ok", body);
          else console.error("[cron] release-holds failed", res.status, body.slice(0, 300));
        })
        .catch((error: unknown) => console.error("[cron] release-holds threw", error)),
    );
  },
};

// Durable Object used by OpenNext's revalidation queue must be re-exported.
// @ts-ignore — generated by the OpenNext build
export { DOQueueHandler } from "./.open-next/worker.js";
